92	/** In-page read: everything the runtime already publishes. No mutation. */
93	async function sample() {
94	  const base = await readState(page);
95	  const extra = await page.evaluate(() => {
96	    const out = {};
97	    try {
98	      const s = window.__paravoxiaJourneyProbe?.getSnapshot?.();
