112	    try {
113	      const lc = window.__voxObjectiveLifecycle?.();
114	      if (lc) {
115	        out.objectiveLifecycleTrace = lc.map((e) => ({ ...e }));
116	        out.objectiveLifecycleCount = lc.length;
117	      }
118	    } catch { /* read-only */ }
119	    try {
120	      const t = window.__voxSfxTrace?.();
121	      if (t) {
122	        out.sfxTriggerCounts = t.triggerCounts ?? null;
123	        out.sfxRecent = (t.events ?? []).slice(-8);
124	        out.sfxTotal = (t.events ?? []).length;
125	      }
126	    } catch { /* read-only */ }
127	    try {
128	      const hud = document.querySelector('[data-story-guidance-hud]');
129	      if (hud) {
130	        out.hud = {
131	          objectiveId: hud.getAttribute('data-objective-id'),
132	          markerLabel: hud.getAttribute('data-objective-marker-label'),
133	          health: hud.getAttribute('data-objective-health'),
134	          requiresMarker: hud.getAttribute('data-objective-requires-marker'),
135	          lines: [...hud.querySelectorAll('li, p, span')]
136	            .map((n) => n.textContent.trim()).filter(Boolean)
137	        };
138	      } else out.hud = null;
139	    } catch { /* read-only */ }
140	    return out;
141	  });
142	  return { ...base, ...extra, tMs: Date.now() };
143	}
