145	async function shoot(label) {
146	  if (noShots) return null;
147	  const file = join(outDir, `${String(frames.length).padStart(4, '0')}-${label.replace(/[^\w.-]+/g, '_')}.png`);
148	  const bytes = await page.screenshot({ path: file });
149	  const stats = frameStats(bytes);
150	  const rec = {
151	    file, label, sha256: createHash('sha256').update(bytes).digest('hex'),
152	    bytes: bytes.length, stats, atMs: Date.now()
153	  };
154	  frames.push(rec);
155	  return rec;
156	}
