158	const started = Date.now();
159	let last = null;
160	let lastAnchor = null;
161	let lastStrip = 0;
162	let pendingAfterShot = null;
163	const objectiveEntries = [];       // one record per objective ENTER
164	const anchorLedger = [];
165	
166	function noteEvent(type, payload) {
167	  const rec = { type, atMs: Date.now(), elapsedMs: Date.now() - started, ...payload };
168	  events.push(rec);
169	  appendFileSync(tracePath, `${JSON.stringify({ kind: 'event', ...rec })}\n`);
170	  tag(`${type} ${JSON.stringify(payload).slice(0, 220)}`);
171	  return rec;
172	}
