174	while (Date.now() - started < seconds * 1000) {
175	  const s = await sample();
176	  appendFileSync(tracePath, `${JSON.stringify({ kind: 'sample', elapsedMs: Date.now() - started, s })}\n`);
177	
178	  const objId = s.hud?.objectiveId ?? s.objectiveId ?? null;
179	  const label = s.hud?.markerLabel ?? s.markerLabel ?? null;
180	  const workOrder = s.objectiveFull?.workOrder ?? null;
181	  const anchor = s.avFull?.anchorId ?? null;
182	  const sfxEnter = s.sfxTriggerCounts?.objectiveEnter ?? 0;
183	
184	  if (pendingAfterShot && Date.now() >= pendingAfterShot.at) {
185	    await shoot(`after-${pendingAfterShot.label}`);
186	    pendingAfterShot = null;
187	  }
188	
189	  if (!last || last.objId !== objId) {
190	    if (last?.objId) {
191	      noteEvent('objective-clear', { objectiveId: last.objId, beat: s.beat, anchor });
192	    }
193	    if (objId) {
194	      const exp = expectations.get(objId) ?? null;
195	      const entry = {
196	        objectiveId: objId, atMs: Date.now(), elapsedMs: Date.now() - started,
197	        beat: s.beat, enterAnchor: anchor,
198	        markerLabel: label, workOrder,
199	        health: s.hud?.health ?? null, requiresMarker: s.hud?.requiresMarker ?? null,
200	        sfxObjectiveEnterAtEntry: sfxEnter,
201	        expectedMarkerLabel: exp?.markerLabel ?? null,
202	        expectedWorkOrder: exp?.workOrder ?? null,
203	        conditionalWorkOrders: exp?.conditionalWorkOrders ?? [],
