205	      };
206	      objectiveEntries.push(entry);
207	      noteEvent('objective-enter', { objectiveId: objId, markerLabel: label, workOrder, anchor });
208	      if (!noShots) await shoot(`obj-enter-${objId}`);
209	    }
210	  } else if (objId && JSON.stringify(last.workOrder) !== JSON.stringify(workOrder)) {
211	    const entry = objectiveEntries[objectiveEntries.length - 1];
212	    const change = {
213	      atMs: Date.now(), elapsedMs: Date.now() - started,
214	      from: last.workOrder, to: workOrder,
