217	    };
218	    entry?.textStates.push(change);
219	    noteEvent('objective-text-change', { objectiveId: objId, to: workOrder, markerLabel: label, anchor, sfxEnterCount: sfxEnter });
220	    if (!noShots) await shoot(`obj-text-${objId}`);
221	  } else if (objId && last.label !== label) {
222	    noteEvent('objective-marker-label-change', { objectiveId: objId, from: last.label, to: label });
223	  }
224	
225	  if (anchor !== lastAnchor) {
226	    if (!noShots) await shoot(`anchor-${anchor ?? 'none'}`);
227	    anchorLedger.push({
228	      anchorId: anchor, atMs: Date.now(), elapsedMs: Date.now() - started,
229	      event: s.avFull?.anchorEvent ?? null, sequence: s.avFull?.activationSequence ?? null,
230	      beat: s.beat, objectiveId: objId, contingent: contingent.has(anchor)
