232	    noteEvent('anchor-change', { from: lastAnchor, to: anchor, sequence: s.avFull?.activationSequence ?? null });
233	    pendingAfterShot = { label: `anchor-${anchor ?? 'none'}`, at: Date.now() + 1200 };
234	    lastAnchor = anchor;
235	  }
236	
237	  if (stripS > 0 && Date.now() - lastStrip >= stripS * 1000) {
238	    lastStrip = Date.now();
