240	  }
241	
242	  last = { objId, label, workOrder, anchor };
243	  await sleep(sampleMs);
244	}
245	
246	const finalState = await sample();
247	const summary = {
248	  schema: 'paravoxia.verifier.cgLifecycleProbe.v0',
249	  runId: '2026-09-05-after-the-hearth',
250	  probe: 'cg-lifecycle-probe.mjs',
