268	    beat: finalState.beat, objectiveId: finalState.hud?.objectiveId ?? null,
269	    markerLabel: finalState.hud?.markerLabel ?? null, health: finalState.hud?.health ?? null,
270	    milestones: finalState.milestones ?? null, anchor: finalState.avFull?.anchorId ?? null,
271	    autopilot: finalState.autopilot ?? null
272	  },
273	  pageErrors: session.pageErrors.slice(0, 20),
274	  sfxNote: 'objectiveEnter counts are runtime SFX queue observations; they are not an audibility or hearing claim.'
275	};
276	writeFileSync(join(outDir, 'summary.json'), `${JSON.stringify(summary, null, 2)}\n`);
277	tag(`wrote ${join(outDir, 'summary.json')} (${frames.length} frames, ${events.length} events)`);
278	await session.stop();
