// --- actions ----------------------------------------------------------------

/** Board the parked ship from foot. */
export function enterShip(): boolean {
  if (snapshot.phase !== 'surface' || snapshot.controlMode !== 'fps') return false;
  if (shipBoardingInterceptor && !shipBoardingInterceptor()) return false;
  setSnapshot({ controlMode: 'flight' });
  return true;
}

/** Leave the landed ship and return to on-foot control. */
export function exitShip(): boolean {
  if (snapshot.phase !== 'surface' || snapshot.controlMode !== 'flight') return false;
  if (shipExitInterceptor && !shipExitInterceptor()) return false;
  setSnapshot({ controlMode: 'fps' });
  for (const listener of shipExitListeners) listener(SHIP_EXIT_RECEIPT);
  return true;
}

/**
=== STORY_COORDINATE ===
  return out;
}

export const STORY_COORDINATE: WorldCoordinate = findStoryCoordinate();

export const STORY_SEED = coordinateToSeed(STORY_COORDINATE.x, STORY_COORDINATE.y);

// Story geometry is authored against the canonical primary planet, never a
// second seed-only generator. Keeping the identity local avoids a dependency
// cycle through tidegardenRoute (which imports STORY_COORDINATE from here).
export const STORY_PRIMARY_WORLD_ID = `${STORY_COORDINATE.x},${STORY_COORDINATE.y}`;

export function isStoryWorld(coordinate: WorldCoordinate): boolean {
  return coordinate.x === STORY_COORDINATE.x && coordinate.y === STORY_COORDINATE.y;
}

